        "code": "#!/usr/bin/env bash\n# Debian / Ubuntu example. On RHEL replace \"apt-get purge\" with \"dnf remove\".\nset -euo pipefail\n\n# 1. Review what starts at boot and what listens on the network\nsystemctl list-unit-files --type=service --state=enabled --no-legend\nsudo ss -tulpn\n\n# 2. Stop + disable + mask services this server does not need.\n#    mask links the unit to /dev/null: nothing can start it again.\nfor svc in avahi-daemon cups rpcbind bluetooth ModemManager; do\n  if systemctl list-unit-files \"${svc}.service\" --no-legend | grep -q .; then\n    sudo systemctl disable --now \"${svc}.service\"\n    sudo systemctl mask \"${svc}.service\"\n  fi\ndone\n\n# 3. Remove the packages: absent code has no vulnerability\nsudo apt-get purge -y telnetd avahi-daemon cups rpcbind\nsudo apt-get autoremove -y\n\n# 4. Forbid loading kernel modules for filesystems nobody uses here\nprintf 'install cramfs /bin/false\\ninstall udf /bin/false\\n' |\n  sudo tee /etc/modprobe.d/hardening.conf >/dev/null\n\n# 5. Verify: only the expected sockets remain\nsudo ss -tulpn\n",
