        "file": "deploy-ssh-hardening.sh",
        "lang": "bash",
        "kind": "secure",
        "code": "# --- On your workstation -------------------------------------------\n# Ed25519 key, 100 KDF rounds to slow down passphrase cracking\nssh-keygen -t ed25519 -a 100 -C \"alice@laptop\" -f ~/.ssh/id_ed25519\n# Install the PUBLIC key on the server (still using the password, once)\nssh-copy-id -i ~/.ssh/id_ed25519.pub alice@192.0.2.10\n\n# --- On the server (keep this session open until the final test!) ---\nsudo groupadd -f ssh-users\nsudo usermod -aG ssh-users alice\n\n# 1. Syntax check: prints nothing and returns 0 when the files are valid\nsudo sshd -t\n\n# 2. Effective configuration, after Include files and defaults\nsudo sshd -T | grep -Ei '^(permitrootlogin|passwordauthentication|maxauthtries|allowgroups) '\n\n# 3. Reload only if the check passed. A reload keeps existing sessions alive.\n#    The unit is named \"ssh\" on Debian/Ubuntu and \"sshd\" on RHEL.\nsudo sshd -t && sudo systemctl reload ssh\n\n# --- From a SECOND terminal on your workstation ---------------------\n# Key login must work...\nssh alice@192.0.2.10 'echo key login OK'\n# ...and a password login must now be refused\nssh -o PubkeyAuthentication=no -o PreferredAuthentications=password alice@192.0.2.10\n",
