        "code": "# For each keyword, sshd keeps the FIRST value it finds: later lines\n# are ignored. This audit reproduces that rule.\n\nCONFIG = \"\"\"\n# --- /etc/ssh/sshd_config.d/50-cloud-init.conf (read first) ---\nPasswordAuthentication yes\n\n# --- /etc/ssh/sshd_config (read after the Include line) ---\nPermitRootLogin no\nPasswordAuthentication no\nMaxAuthTries 3\nX11Forwarding yes\n\"\"\"\n\nEXPECTED = {\n    \"permitrootlogin\": \"no\",\n    \"passwordauthentication\": \"no\",\n    \"maxauthtries\": \"3\",\n    \"x11forwarding\": \"no\",\n    \"allowgroups\": None,  # any value is fine, but the keyword must be set\n}\n\neffective = {}\nfor line in CONFIG.splitlines():\n    line = line.strip()\n    if not line or line.startswith(\"#\"):\n        continue\n    keyword, _, value = line.partition(\" \")\n    # setdefault keeps the first value seen: exactly what sshd does\n    effective.setdefault(keyword.lower(), value.strip())\n\nproblems = 0\nfor keyword, wanted in EXPECTED.items():\n    actual = effective.get(keyword)\n    if actual is None:\n        print(f\"FAIL {keyword}: not set\")\n        problems += 1\n    elif wanted is not None and actual != wanted:\n        print(f\"FAIL {keyword}: {actual} (expected {wanted})\")\n        problems += 1\n    else:\n        print(f\"PASS {keyword}: {actual}\")\n\nprint(f\"\\n{problems} problem(s) found\")\n",
